import{j as e}from"./motion-C33zLNOn.js";import{L as t}from"./LegalLayout-DDqv9NbS.js";import{u as o}from"./index-m8uOo6rM.js";import"./react-vendor-BlkHZrIR.js";import"./PageHero-CA7yq6Fy.js";import"./check-BbDgy76J.js";import"./three-DvkfnHy2.js";function c(){return o(),e.jsx(t,{title:"Delete your account",updated:"October 2026",minutes:5,wall:"/media/walls/raat.jpg",intro:"You can delete a Xelvic account from inside the app in four taps, and you can ask us to do it from here without installing anything. Either way the account is hidden the moment you ask, and gone for good 30 days later. This page is the whole of it.",inShort:["In the app: Settings → Account → Delete account. It asks for your password, because it is not undoable by a tap on a borrowed phone.","The account goes dark straight away — nobody can find you, message you, or see you on a list.","Nothing is erased for 30 days. Sign back in with your number and password inside that window and everything returns exactly as it was.","After 30 days the account is deleted permanently, and that cannot be reversed by us or by anybody else.","No app to hand? Write to privacy@xelvic.app from your account’s own address and a person will delete it for you."],glance:[{label:"Hidden after",value:"Immediately"},{label:"Erased after",value:"30 days"},{label:"Change your mind",value:"Sign back in"},{label:"Web request",value:"By email"}],sections:[{heading:"Delete it from inside the app",body:["Open Settings, go to Account, and choose Delete account. The app asks for your password before it does anything — not the fact that you are already signed in, but the password itself. That check is deliberate: a phone left unlocked on a table should not be able to throw the account away in one tap.","Confirm it and the account is hidden at once. It stops appearing to anybody else: your profile cannot be found, you cannot be messaged, you come off the lists and counts you were on, and the people you were talking to stop seeing you there. There is nothing to wait for.","The app then tells you what it has done and how long you have to change your mind, rather than leaving you to guess. If you have already done this and want to know where you stand, the account is recoverable for 30 days from the moment you asked."],points:["Settings → Account → Delete account, in the app.","Your password is required, so a borrowed phone cannot do it.","Hiding is immediate; every route to you closes at once.","The app states the 30-day window when you confirm."],app:"Your account will be deleted in 30 days. Log in again to recover it."},{heading:"Ask us to delete it, without the app",body:["If you no longer have the app installed, or you cannot sign in to reach the setting, write to privacy@xelvic.app and ask us to delete the account. This is the route for the case where the setting is out of reach.","Send it from the email address on the account if there is one, and name the handle or the phone number the account was opened with. A request about your own account can only be acted on once we are satisfied it is yours, and those two details are what settle it. If you cannot reach the account’s own address at all, say so in the first line and tell us what you can still prove — the request still gets read by a person.","We acknowledge the request and then delete the account on the same terms as the in-app route: hidden at once, erased after the 30 days. Nobody is asked to reinstall anything, and there is no form to fill in."],points:["Write to privacy@xelvic.app and ask for the account to be deleted.","Name the handle or the phone number it was opened with.","Write from the address on the account, where there is one.","Answered within 30 days, and read by a person either way."]},{heading:"What deleting actually removes",body:["The account itself goes: your profile, your handle, your picture, your bio, your date of birth and your settings. So does everything hanging off it — the messages you sent and your place in the conversations you were in, the moments, drops, vibes and memories you put up, the sparks you were keeping, the lists you were on, and any creator deals you were part of. All of it goes with the account rather than being left behind under a number.","The delete is the removal of your account row, and everything that points at it goes with it. There is no second library of you kept somewhere else, and no shadow profile that survives the deletion. A conversation with other people in it stays where it is for them, minus you and minus what you sent.","One honest exception, and it is the only one. If somebody complained about something you posted, the record of that complaint stays in the moderation queue with the link to you removed. A queue somebody can empty by deleting their account is not a queue, so the record of what was looked at outlives the account it was about. It names no one afterwards."],points:["Profile, handle, picture, bio, date of birth, settings.","The messages you sent, and your place in those conversations.","Moments, drops, vibes, memories, playlists and saved things.","Sparks, lists, and any creator deals you were part of.","Kept: a complaint about your content, with the link to you removed."]},{heading:"The 30 days, and how to use them",body:["The window exists so a bad evening is not a permanent decision. For 30 days nothing is actually erased — the account is hidden, which is why signing back in is all it takes to get everything back exactly as it was. Same handle, same conversations, same posts, same sparks.","The window is not a promise that deletion is reversible. Past the 30 days there is no route back, for you or for us, and nobody at Xelvic can restore an account that the purge has taken. If you are not certain, sign back in before the window closes rather than writing to us after it.","If you asked us by email rather than in the app, the same clock applies from the moment we action the request, and we tell you when that is."],points:["Sign in with your number and password inside 30 days to recover.","Everything returns exactly as it was — nothing is partially kept.","Past 30 days the account is erased, and no one can bring it back.","Not sure? Recover first, decide afterwards."],app:"Hidden right away, kept for 30 days, then gone for good."},{heading:"If you want less than a deletion",body:["Deleting is the heaviest of the options, and it is not the only one. Most of what people delete an account to escape can be dealt with without losing it.","If you want a conversation out of sight rather than gone, move it into the Vault — it leaves the convo list and turns up behind a code only you know. If you want a specific post down, take it down. If you want to stop somebody reaching you without either of you losing the thread, block them. And if you only want a break, sign out of every phone but one in a single press rather than closing the account at all.","Each of these is reversible, which the deletion is not. If none of them is enough, the deletion is the right door — and the 30 days are there for the case where it turns out it was not."],points:["Vault a conversation — hidden, not gone.","Take down a post, or switch its comments off.","Block somebody instead of closing the account.","Sign out of every other phone in one press."],app:"Every phone but this one, in one press."},{heading:"Before you delete",body:["A few things are worth knowing while the account still exists, because two of them cannot be done afterwards and one of them can save you the deletion entirely.","A vault code cannot be recovered, and neither can an account past the 30 days — those are the two one-way doors. Your photos and videos live on this phone as well as on the account, so anything you want to keep should be saved to the device before you delete. And if the reason is a person, blocking them is faster than leaving and takes nothing with it.","If what you actually want is your data rather than the end of the account, ask us for a copy instead. Write to privacy@xelvic.app and say what you want — a copy of what we hold, a correction, or the deletion itself — and a person will deal with it. There is no charge and no argument to win first."],points:["Save anything you want to keep to the phone first.","A vault code has no recovery, then or later.","A block may be the smaller answer to the same problem.","Want the data, not the end of the account? Ask for a copy."]}],related:[{label:"Privacy Policy",to:"/privacy"},{label:"Your Data",to:"/data"},{label:"Terms",to:"/terms"},{label:"Settings",to:"/settings"},{label:"Contact",to:"/contact"}],contact:{label:"Email privacy@xelvic.app",href:"mailto:privacy@xelvic.app",note:"Ask for the account to be deleted, ask for a copy of what we hold, or ask us to correct something. A person reads this inbox, and every request about your own data is answered within 30 days."}})}export{c as default};
